            for(boolean red:new boolean[]{false,true}){var expiring=new GolemOrb(level,melee,null,red);cleanup.add(expiring);expiring.moveTo(position.getCenter().add(0,20,0));expiring.tickCount=red?240:160;tick(expiring);check.accept(expiring.isRemoved(),"original"+(red?240:160)+" tick lifetime expires after boundary");}
