            var saved=new CompoundTag();golem.addAdditionalSaveData(saved);var restored=R5Entities.ELDRITCH_GOLEM.get().create(level);restored.getAttribute(ChampionSystem.MODIFIER).setBaseValue(-1);cleanup.add(restored);restored.readAdditionalSaveData(saved);check.accept(restored.isHeadless()&&restored.getSpawnTimer()==0&&restored.getBeamCharge()==0&&restored.getRestrictCenter().equals(position)&&restored.getRestrictRadius()==24,"NBT keeps headless state and home while original transient timers reset");
            var p1=player(level,"AggroA",position.getCenter().add(2,0,0));var p2=player(level,"AggroB",position.getCenter().add(-2,0,0));cleanup.add(p1);cleanup.add(p2);level.addFreshEntity(p1);level.addFreshEntity(p2);check.accept(level.getEntity(p1.getId())==p1&&level.getEntity(p2.getId())==p2,"aggro fixture players are real entity-manager participants");
            var mapField=ThaumcraftBoss.class.getDeclaredField("aggro");mapField.setAccessible(true);@SuppressWarnings("unchecked")var weights=(Map<Integer,Integer>)mapField.get(golem);var update=ThaumcraftBoss.class.getDeclaredMethod("updateAggro");update.setAccessible(true);
            weights.put(p1.getId(),10);weights.put(p2.getId(),40);golem.setTarget(p1);golem.setHealth(125);update.invoke(golem);check.accept(golem.getTarget()==p2&&golem.getMaxHealth()==300&&golem.getAttributeValue(Attributes.ATTACK_DAMAGE)==10.5&&golem.getHealth()==150,"choice A resolves candidate ID, switches above thresholds, counts both players and retains health fraction");
            weights.put(p1.getId(),41);weights.put(p2.getId(),40);golem.setTarget(p2);update.invoke(golem);check.accept(golem.getTarget()==p2&&golem.getMaxHealth()==300,"choice A counts participants even when no score reaches retarget threshold");
            weights.put(p1.getId(),1025);weights.put(p2.getId(),1000);update.invoke(golem);check.accept(golem.getTarget()==p2,"choice A retains strict +25 switching boundary");weights.put(p1.getId(),1100);update.invoke(golem);check.accept(golem.getTarget()==p2,"choice A retains strict multiplier1.1 switching boundary");weights.put(p1.getId(),1101);update.invoke(golem);check.accept(golem.getTarget()==p1,"choice A switches only above both original thresholds");golem.setTarget(p2);
            p1.moveTo(position.getCenter().add(129,0,0));update.invoke(golem);check.accept(!weights.containsKey(p1.getId())&&golem.getMaxHealth()==250&&golem.getHealth()==125,"out-of-range aggro is removed and participant scaling preserves health fraction");
            var modifiers=ThaumcraftBoss.class.getDeclaredMethod("updateParticipantModifiers",int.class);modifiers.setAccessible(true);modifiers.invoke(golem,20);check.accept(golem.getMaxHealth()==500&&golem.getAttributeValue(Attributes.ATTACK_DAMAGE)==12.5,"participant scaling caps at five original +50HP/+0.5damage steps");
            var death=ThaumcraftBoss.class.getDeclaredMethod("dropCustomDeathLoot",ServerLevel.class,net.minecraft.world.damagesource.DamageSource.class,boolean.class);death.setAccessible(true);death.invoke(melee,level,level.damageSources().generic(),true);var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,melee.getBoundingBox().inflate(6));cleanup.addAll(drops);var pearl=drops.stream().filter(e->e.getItem().is(R3Equipment.PRIMAL_PEARL.get())).findFirst().orElseThrow();check.accept(pearl instanceof SpecialItemEntity&&!(pearl instanceof PermanentItemEntity)&&pearl.getDeltaMovement().equals(new Vec3(0,(double).1f,0))&&pearl.hasPickUpDelay(),"boss pearl uses expiring special item, original upward motion and pickup delay");check.accept(drops.stream().anyMatch(e->e.getItem().is(R5Content.LOOT_BAGS.get(2).get())),"boss drops original rare loot bag");
